```csharp
// به‌روزرسانی انبوه در یک SQL
await db.Orders.Where(o => o.Status == Status.Pending && o.CreatedAt < cutoff)
    .ExecuteUpdateAsync(s => s.SetProperty(o => o.Status, Status.Expired), ct);

// keyset pagination
var page = await db.Posts.Where(p => p.Id < lastId).OrderByDescending(p => p.Id).Take(20).ToListAsync(ct);
